-- Remove the Saison record (ADR 0024, Fahrplan SAI3): event_season, event_season_anchor, task/checklist/permit.season_id,
-- template_item.scope and their enums. Generated by drizzle-kit, REORDERED by hand (data first, then constraints,
-- indexes, columns, tables, types: the generated DROP TABLE … CASCADE came first and would have dropped the foreign
-- keys the later statements drop by name), plus the HAND-WRITTEN data step below. Only synthetic data exists
-- (production has not started), so the season work is deleted, not moved.
-- HAND-WRITTEN BEGIN
-- 1. Files attached to a season task move to the task's permit, else to the market's Ort, so none is lost
--    (document.task_id is ON DELETE restrict and a file needs at least one link).
UPDATE "app"."document" d SET
	"permit_id" = COALESCE(d."permit_id", t."permit_id"),
	"venue_id" = CASE WHEN d."permit_id" IS NULL AND t."permit_id" IS NULL THEN COALESCE(d."venue_id", ep."venue_id") ELSE d."venue_id" END,
	"task_id" = NULL
FROM "app"."task" t
JOIN "app"."event_season" s ON s."id" = t."season_id"
JOIN "app"."event_preset" ep ON ep."id" = s."preset_id"
WHERE d."task_id" = t."id";--> statement-breakpoint
-- 2. Notifications and escalations about season tasks would point nowhere.
DELETE FROM "app"."notification" WHERE "subject_type" = 'task'
	AND "subject_id" IN (SELECT "id" FROM "app"."task" WHERE "season_id" IS NOT NULL);--> statement-breakpoint
DELETE FROM "app"."escalation_log" WHERE "subject_type" = 'task'
	AND "subject_id" IN (SELECT "id" FROM "app"."task" WHERE "season_id" IS NOT NULL);--> statement-breakpoint
-- 3. Season tasks (with their subtasks, comments through ON DELETE cascade) and season checklists.
DELETE FROM "app"."task" WHERE "season_id" IS NOT NULL;--> statement-breakpoint
DELETE FROM "app"."checklist" WHERE "season_id" IS NOT NULL;--> statement-breakpoint
-- 4. Season-scoped template items (their child items go with them, template_item_parent is ON DELETE cascade).
DELETE FROM "app"."template_item" WHERE "scope" = 'season';--> statement-breakpoint
-- 5. Template tasks no longer apply for a permit covering several dates (a template task only applies for a
--    per_event permit): they keep their history but lose the link.
UPDATE "app"."task" t SET "permit_id" = NULL
FROM "app"."permit" p
JOIN "app"."permit_requirement" pr ON pr."id" = p."requirement_id"
WHERE t."permit_id" = p."id" AND t."source" = 'template' AND pr."cadence" <> 'per_event';--> statement-breakpoint
-- 6. A permit covering several dates that is still to be applied for gets its own "… beantragen" task (no event,
--    due at apply-by 23:59 Berlin, assigned to the permit's responsible person), as the logbook fill makes it.
--    Its apply task used to be the deleted season task. One audit row per task (actor_id NULL: a system entry).
WITH created AS (
INSERT INTO "app"."task" ("id", "permit_id", "source", "title", "phase", "category", "priority", "duty_role_id",
	"assignee_id", "due_at")
SELECT
	gen_random_uuid(), p."id", 'permit', pr."title" || ' beantragen', 'pre', 'permits', 'normal',
	(SELECT dr."id" FROM "app"."duty_role" dr WHERE dr."key" = 'permits'),
	p."responsible_staff_member_id",
	CASE WHEN p."apply_by" IS NULL THEN NULL ELSE (p."apply_by" + time '23:59') AT TIME ZONE 'Europe/Berlin' END
FROM "app"."permit" p
JOIN "app"."permit_requirement" pr ON pr."id" = p."requirement_id"
WHERE pr."cadence" <> 'per_event'
	AND p."archived_at" IS NULL
	AND p."status" IN ('not_started', 'preparing')
	AND NOT EXISTS (
		SELECT 1 FROM "app"."task" t
		WHERE t."permit_id" = p."id" AND t."source" = 'permit' AND t."status" <> 'cancelled'
	)
RETURNING "id", "permit_id"
)
INSERT INTO "app"."audit_log" ("id", "action", "entity_type", "entity_id", "diff")
SELECT gen_random_uuid(), 'task.create', 'task', c."id",
	jsonb_build_object('backfill', true, 'source', 'remove_saison', 'permitId', c."permit_id")
FROM created c;--> statement-breakpoint
-- HAND-WRITTEN END
ALTER TABLE "app"."checklist" DROP CONSTRAINT "checklist_one_owner";--> statement-breakpoint
ALTER TABLE "app"."permit" DROP CONSTRAINT "permit_season_id_event_season_id_fk";
--> statement-breakpoint
ALTER TABLE "app"."checklist" DROP CONSTRAINT "checklist_season_id_event_season_id_fk";
--> statement-breakpoint
ALTER TABLE "app"."task" DROP CONSTRAINT "task_season_id_event_season_id_fk";
--> statement-breakpoint
DROP INDEX "app"."permit_season_id_index";--> statement-breakpoint
DROP INDEX "app"."checklist_season_id_index";--> statement-breakpoint
DROP INDEX "app"."task_season_id_status_index";--> statement-breakpoint
ALTER TABLE "app"."permit" DROP COLUMN "season_id";--> statement-breakpoint
ALTER TABLE "app"."checklist" DROP COLUMN "season_id";--> statement-breakpoint
ALTER TABLE "app"."task" DROP COLUMN "season_id";--> statement-breakpoint
ALTER TABLE "app"."template_item" DROP COLUMN "scope";--> statement-breakpoint
DROP TABLE "app"."event_season_anchor";--> statement-breakpoint
DROP TABLE "app"."event_season";--> statement-breakpoint
ALTER TABLE "app"."checklist" ADD CONSTRAINT "checklist_one_owner" CHECK (not ("app"."checklist"."event_id" is not null and "app"."checklist"."permit_id" is not null));--> statement-breakpoint
DROP TYPE "app"."event_season_status";--> statement-breakpoint
DROP TYPE "app"."template_item_scope";
